<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Role\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Create\RoleCreateAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Delete\RoleDeleteAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\List\RoleListAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Retrieve\RoleRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Update\RoleUpdateAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlyForRootAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(RoleCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('RoleCreateAllowDecision', $proposal);
    }
    public function checkDelete(RoleDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('RoleDeleteAllowDecision', $proposal);
    }
    public function checkList(RoleListAllowDecision $proposal): AllowDecision
    {
        return $this->check('RoleListAllowDecision', $proposal);
    }
    public function checkRetrieve(RoleRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('RoleRetrieveAllowDecision', $proposal);
    }
    public function checkUpdate(RoleUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('RoleUpdateAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on OnlyForRootAllow Role");
        $span = $this->startSpan("Check " . $name . " on OnlyForRootAllow Role");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!(($identity->hasScope("platform:global_access") && $identity->hasRole("admin")))) {
                    $proposal->deny('Disabled if not OnlyForRoot');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
